"Control flow is just messages sent to objects - so you can add your own."
Boolean extend [
    unless: aBlock [ ^self ifFalse: aBlock ]
]

Object subclass: Echo [
    doesNotUnderstand: aMessage [ ^'echo: ', aMessage selector ]
]

Transcript
    showCr: (3 + 4) printString;
    showCr: (3 perform: #between:and: with: 1 with: 5) printString;
    showCr: 3 class name, ' ', true class name;
    showCr: ((2 > 3) unless: ['2 > 3 is false']);
    showCr: (Echo new frobnicate: 42).
